    "id": "accounting-workbench",
    "title": "會計工作台",
    "summary": "集中檢查來源單據、科目、傳票與差異。費用項目是員工申請選項，會計科目是入帳分類；分類不確定時交由會計確認，不可直接以 AI 建議當成正式入帳。",
    "keywords": [
      "會計",
      "科目",
      "入帳",
      "傳票",
      "分錄"
    ],
    "path": "/accounting/workbench",
    "module": "accounting",
    "category": "財務會計",
    "group": "finance",
    "sections": {
      "steps": [
        "在會計工作台選擇資料範圍，查看來源單据與待辦。",
        "由缺發票或差異追溯訂單、憑證、付款及傳票，確認歸屬日期與科目。",
        "分類不確定時交由會計核實，再依正式入帳與核准流程處理。"
      ],
      "boundaries": [
        "報銷項目、憑證、應付、付款、會計分錄是不同資料層次。",
        "AI 建議、核准費用或標記發票存在都不能單獨視為正式過帳。"
      ],
      "related": [
        "journal-entries",
        "chart-of-accounts",
        "reconciliation",
        "reports"
      ]
    },
    "translations": {
      "en": {
        "title": "Accounting workbench",
        "summary": "Review source documents, accounts, journals and differences. Expense items are employee choices; accounting accounts classify posting. Uncertain AI suggestions require accounting review.",
        "category": "Finance and accounting",
        "keywords": [
          "Accounting workbench",
          "accounting"
        ],
        "sections": {
          "steps": [
            "Select the data range in the accounting workbench and review source documents and pending work.",
            "Trace missing invoices or differences to orders, evidence, payments and journals; verify dates and accounts.",
            "Have accounting resolve uncertain classifications before formal posting and approval."
          ],
          "boundaries": [
            "Reimbursement items, evidence, payables, payments and journals represent different records.",
            "AI suggestions, expense approval or an invoice-present flag alone do not prove formal posting."
          ],
          "related": [
            "journal-entries",
            "chart-of-accounts",
            "reconciliation",
            "reports"
          ]
        }
      }
    },
    "permissions": [
      "accounts:read",
      "journal_entries:read"
    ],
